        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,0) avg_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name IN ('RouteRepository.findAll','RouteController.queryAll') GROUP BY ALL", "claim": "RouteRepository.findAll fails in about 30 s on every call, with no child database span, while the handler returns 403."},
        {"kind": "metric", "sql": "SELECT p, service_name, metric, round(avg(value),2) avg_v, round(max(value),2) mx FROM (SELECT 'abn' p, * FROM abnormal_metrics UNION ALL SELECT 'norm', * FROM normal_metrics) WHERE service_name IN ('ts-route-service','mysql') AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set') GROUP BY ALL ORDER BY 2,3,1", "claim": "Route-service and mysql CPU and memory stay flat and low, so the failure is not resource exhaustion."}
